namespace PatternsLab.Problems.Builder;
public sealed class CourseRegistration
{
    public string StudentEmail { get; } public string CourseCode { get; } public string AccessMode { get; } public string? GroupCode { get; } public string? DiscountCode { get; } public bool SendWhatsApp { get; } public bool SendEmailWelcome { get; } public string? MentorNote { get; } public DateOnly? PreferredStart { get; }
    private CourseRegistration(RegistrationBuilder b) { if (string.IsNullOrWhiteSpace(b.StudentEmail) || string.IsNullOrWhiteSpace(b.CourseCode)) throw new InvalidOperationException("Email and course are required."); if (b.AccessMode == "LiveGroup" && string.IsNullOrWhiteSpace(b.GroupCode)) throw new InvalidOperationException("LiveGroup requires GroupCode."); if (b.AccessMode == "VideosOnly" && !string.IsNullOrWhiteSpace(b.GroupCode)) throw new InvalidOperationException("VideosOnly cannot have GroupCode."); StudentEmail=b.StudentEmail; CourseCode=b.CourseCode; AccessMode=b.AccessMode; GroupCode=b.GroupCode; DiscountCode=b.DiscountCode; SendWhatsApp=b.SendWhatsApp; SendEmailWelcome=b.SendEmailWelcome; MentorNote=b.MentorNote; PreferredStart=b.PreferredStart; }
    public override string ToString() { return $"{StudentEmail} → {CourseCode} [{AccessMode}] group={GroupCode ?? "-"}"; }
    public static RegistrationBuilder For(string email, string course) { return new RegistrationBuilder(email, course); }
    public sealed class RegistrationBuilder { internal string StudentEmail; internal string CourseCode; internal string AccessMode="VideosOnly"; internal string? GroupCode; internal string? DiscountCode; internal bool SendWhatsApp; internal bool SendEmailWelcome; internal string? MentorNote; internal DateOnly? PreferredStart; internal RegistrationBuilder(string email,string course) { StudentEmail=email; CourseCode=course; } public RegistrationBuilder LiveGroup(string group) { AccessMode="LiveGroup"; GroupCode=group; return this; } public RegistrationBuilder VideosOnly() { AccessMode="VideosOnly"; return this; } public RegistrationBuilder WithGroupCode(string group) { GroupCode=group; return this; } public RegistrationBuilder WithDiscount(string code) { DiscountCode=code; return this; } public RegistrationBuilder SendWelcomeByEmail() { SendEmailWelcome=true; return this; } public RegistrationBuilder SendWelcomeByWhatsApp() { SendWhatsApp=true; return this; } public RegistrationBuilder WithMentorNote(string note) { MentorNote=note; return this; } public RegistrationBuilder StartingOn(DateOnly date) { PreferredStart=date; return this; } public CourseRegistration Build() { return new CourseRegistration(this); } }
}
public static class RegistrationCallSites { public static CourseRegistration CreateLiveStudentUgly() { return CourseRegistration.For("sara@mail.com","SEF-101").LiveGroup("G1").WithDiscount("EARLY10").SendWelcomeByEmail().SendWelcomeByWhatsApp().WithMentorNote("Needs evening slot").StartingOn(new DateOnly(2026,10,1)).Build(); } public static CourseRegistration CreateVideosOnlyUgly() { return CourseRegistration.For("ali@mail.com","SEF-101").VideosOnly().SendWelcomeByEmail().Build(); } }
